={
  "embeds": [
    {
      "title": "{{ $json.workflow.name }}: `{{ $json.workflow.id }}`",
      "color": 16711680,
      "fields": [
        {
          "name": "Error Message",
          "value": "```\n{{ ((s) => s.length > 1000 ? s.slice(0, 1000) + '...' : s)(($json.execution.error.message).toString()) }}\n```"
        },
        {
          "name": "Error Stack",
          "value": "```\n{{ ((s) => s.length > 1000 ? s.slice(0, 1000) + '...' : s)(($json.execution.error.stack).toString()) }}\n```"
        },
        {
          "name": "Execution",
          "value": "ID: `{{ $json.execution.id }}`\nURL: `{{ $json.execution.url }}`\nRetry Of: `{{ $json.execution.retryOf }}`\nLast Node Executed: `{{ $json.execution.lastNodeExecuted }}`\nMode: `{{ $json.execution.mode }}`"
        }
      ]
    }
  ]
}

